(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.022-t*0.18)*12 + Math.sin((x+y)*0.01+t*0.15)*8;
  const w1y = Math.cos(y*0.02-t*0.22)*18 + Math.sin(x*0.025+t*0.2)*12 + Math.cos((x-y)*0.012-t*0.12)*8;
  const x2 = x + w1x, y2 = y + w1y;
  const w2x = Math.sin(x2*0.03-t*0.4)*6 + Math.cos(y2*0.028+t*0.35)*5;
  const w2y = Math.cos(y2*0.025+t*0.38)*6 + Math.sin(x2*0.032-t*0.42)*5;
  const sx = x2 + w2x, sy = y2 + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.8],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.2],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.9],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.1],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.7],
    [80+Math.sin(t*0.7+3)*60, 40+Math.cos(t*0.45+2)*40, 0.14, 2.1, 1.3],
    [400+Math.cos(t*0.55+1)*70, 220+Math.sin(t*0.65+4)*50, 0.11, 1.8, 0.6],
    [200+Math.sin(t*0.42+6)*110, 180+Math.cos(t*0.38+3)*70, 0.055, 2.4, 1.0],
    [300+Math.cos(t*0.62+2)*90, 100+Math.sin(t*0.48+5)*80, 0.095, 2.0, 0.85]
  ];
  let aS = 0, iS = 0, dif = 0;
  for (const [sX, sY, f, sp, amp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp) * amp;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * amp;
    dif += Math.sin(d*f*1.3 - t*sp*0.4 + 2.8) * amp * 0.5;
  }
  const n = src.length;
  const act = aS/n, inh = iS/n, df = dif/n;
  const bg1 = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2 = Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3 = Math.sin(sx*0.08+sy*0.06-t*0.5)*0.15 + Math.sin(sx*0.05-sy*0.09+t*0.7)*0.15;
  const bg = bg1 + bg2 + bg3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const sp1 = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2 = Math.sin(dist*0.07-ang*5+t*0.8)*0.2 + Math.sin(dist*0.03+ang*2-t*2.1)*0.15;
  const spiral = sp1 + sp2;
  const c1 = Math.sin(sx*0.15)*Math.sin(sy*0.15);
  const c2 = Math.sin(sx*0.08+t*0.3)*Math.sin(sy*0.1-t*0.25)*0.7;
  const c3 = Math.sin((sx+sy)*0.1+t)*0.5;
  const cell = Math.tanh((c1+c2+c3)*1.2)*0.3;
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const rd2 = Math.tanh((df*0.8 - act*0.3 + inh*0.5 + bg*0.2)*1.8);
  const reaction = rd1*0.7 + rd2*0.3;
  const edge = Math.abs(reaction) > 0.65 ? 1.0 + (Math.abs(reaction)-0.65)*1.2 : 1.0;
  const glow = Math.max(0, Math.abs(reaction)-0.5)*0.4;
  const blend = reaction*0.65 + cell*0.2 + glow*0.15;
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,45],[10,35,80],[12,65,105],[18,110,120],
    [35,155,130],[120,175,80],[195,185,60],[210,145,55],
    [205,105,65],[175,60,55],[130,35,55],[75,18,48],[5,12,45]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const lum = 0.82+Math.sin(reaction*Math.PI)*0.18;
  const vig = 1.0 - Math.sqrt((x-cx)**2+(y-cy)**2)*0.0008;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge*vig)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge*vig)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge*vig)|0
  ];
}
